import{_ as r,K as l,a as s,c as n,ac as c,q as t,b as i,k as u}from"./chunks/framework.BSuaGltH.js";const I=JSON.parse('{"title":"办公系统需求草稿","description":"办公系统用户角色、密码找回和权限范围草稿","frontmatter":{"title":"办公系统需求草稿","description":"办公系统用户角色、密码找回和权限范围草稿","sources":[{"repository":"jekyall_blog","file":"_posts/Dev/软件设计/办公系统设计稿.md"}],"showdocs":{"topics":[{"id":"architecture","title":"架构风格与模块边界","link":"/topics/architecture/"}],"kind":"架构取舍与原文","scope":"historical","audience":"general","group":"原理与设计","summary":"办公系统用户角色、密码找回和权限范围草稿","status":"active","related":[{"title":"库存服务的端口与适配器实践","link":"/principles/distributed-architecture/architecture/cases/application","kind":"库存边界实践","scope":"general","audience":"general"},{"title":"模块边界、数据所有权与架构决策","link":"/principles/distributed-architecture/architecture/module-boundaries","kind":"模块与交互决策","scope":"general","audience":"general"},{"title":"时序图示例","link":"/principles/distributed-architecture/architecture/cases/sequence-diagram","kind":"架构取舍与原文","scope":"general","audience":"general"},{"title":"面对面建群","link":"/principles/distributed-architecture/architecture/cases/%E9%9D%A2%E5%AF%B9%E9%9D%A2%E5%BB%BA%E7%BE%A4","kind":"架构取舍与原文","scope":"general","audience":"general"},{"title":"朋友圈（广场设计）","link":"/principles/distributed-architecture/architecture/cases/%E6%9C%8B%E5%8F%8B%E5%9C%88(%E5%B9%BF%E5%9C%BA%E8%AE%BE%E8%AE%A1)","kind":"架构取舍与原文","scope":"historical","audience":"general"}],"prev":{"text":"库存服务的端口与适配器实践","link":"/principles/distributed-architecture/architecture/cases/application"},"next":{"text":"面对面建群","link":"/principles/distributed-architecture/architecture/cases/%E9%9D%A2%E5%AF%B9%E9%9D%A2%E5%BB%BA%E7%BE%A4"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"库存服务的端口与适配器实践","link":"/principles/distributed-architecture/architecture/cases/application"},"next":{"text":"面对面建群","link":"/principles/distributed-architecture/architecture/cases/%E9%9D%A2%E5%AF%B9%E9%9D%A2%E5%BB%BA%E7%BE%A4"}},"headers":[],"relativePath":"principles/distributed-architecture/architecture/cases/办公系统设计稿.md","filePath":"principles/distributed-architecture/architecture/cases/办公系统设计稿.md"}'),d={name:"principles/distributed-architecture/architecture/cases/办公系统设计稿.md"};function o(p,e,h,m,k,b){const a=l("Mermaid");return s(),n("div",null,[e[0]||(e[0]=c('<h1 id="办公系统需求草稿" tabindex="-1">办公系统需求草稿 <a class="header-anchor" href="#办公系统需求草稿" aria-label="Permalink to &quot;办公系统需求草稿&quot;">​</a></h1><p><span id="办公系统"></span><span id="人员管理"></span><span id="个人中心"></span><span id="财务"></span><span id="考勤"></span><span id="效绩考核"></span><span id="日常工作安排"></span><span id="系统公告"></span><span id="审计"></span></p><h2 id="用户模块" tabindex="-1">用户模块 <a class="header-anchor" href="#用户模块" aria-label="Permalink to &quot;用户模块&quot;">​</a></h2><p>人员管理与个人中心尚待细化。</p><h3 id="用户分类" tabindex="-1">用户分类 <a class="header-anchor" href="#用户分类" aria-label="Permalink to &quot;用户分类&quot;">​</a></h3><ul><li>超级管理员</li><li>普通用户</li></ul><h3 id="登录切换" tabindex="-1">登录切换 <a class="header-anchor" href="#登录切换" aria-label="Permalink to &quot;登录切换&quot;">​</a></h3><ul><li>超级管理登录 <ul><li>密码找回 <ul><li>密保</li><li>手机验证码</li><li>邮箱验证码或者激活</li></ul></li></ul></li><li>普通用户 <ul><li>找回密码 <ul><li>密保</li><li>手机验证码</li><li>邮箱验证码或者激活</li><li>联系超级管理员</li></ul></li></ul></li></ul><h2 id="权限管理" tabindex="-1">权限管理 <a class="header-anchor" href="#权限管理" aria-label="Permalink to &quot;权限管理&quot;">​</a></h2><h3 id="权限设计规则" tabindex="-1">权限设计规则 <a class="header-anchor" href="#权限设计规则" aria-label="Permalink to &quot;权限设计规则&quot;">​</a></h3><ul><li>企业层级权限管理</li></ul><h2 id="待细化模块" tabindex="-1">待细化模块 <a class="header-anchor" href="#待细化模块" aria-label="Permalink to &quot;待细化模块&quot;">​</a></h2><p>财务、考勤、绩效考核、日常工作安排、系统公告与审计尚未形成设计正文。</p><h2 id="把角色清单变为授权边界" tabindex="-1">把角色清单变为授权边界 <a class="header-anchor" href="#把角色清单变为授权边界" aria-label="Permalink to &quot;把角色清单变为授权边界&quot;">​</a></h2><p>以下是对历史需求的设计推演，不代表现有系统实现。角色决定“能做什么”，企业与部门范围决定“能对哪些数据做”。例如部门管理员能修改本部门考勤，但不应因为拥有考勤编辑角色就能改其他企业的数据。请求应从可信登录上下文取得身份和企业范围，再核对目标资源所属范围；不能直接相信客户端传来的企业ID。</p><p>超级管理员还需区分企业内管理与跨企业平台管理，否则一个名字会掩盖很大的权限差异。权限撤销后，缓存或会话何时生效需要明确；导出、批量修改与详情读取都要执行相同范围校验。审计至少记录操作者、目标、动作、结果和时间，避免只记录“接口调用成功”。</p>',16)),t(a,{source:""}),e[1]||(e[1]=i("h2",{id:"密码恢复与业务模块如何落地",tabindex:"-1"},[u("密码恢复与业务模块如何落地 "),i("a",{class:"header-anchor",href:"#密码恢复与业务模块如何落地","aria-label":'Permalink to "密码恢复与业务模块如何落地"'},"​")],-1)),e[2]||(e[2]=i("p",null,"旧稿列出的密保、短信、邮箱是历史候选，不应默认全部启用。恢复流程应先建立一次有时效、次数限制和单次使用语义的验证挑战，核验后仅授予重置密码的能力，完成后使挑战失效，并按策略撤销旧会话。联系管理员应是单独的受审计恢复流程，不能让管理员读取用户旧密码。",-1)),e[3]||(e[3]=i("p",null,"待细化模块可以先按数据责任拆解：考勤记录事实与更正记录；绩效定义评价周期及审批状态；财务区分申请、审核和执行；公告定义发布者与可见范围。跨模块交互要说明哪些事实可以修改、谁能审批、失败如何恢复。图示只是恢复流程的建议约束，验证渠道与审批规则仍待产品确定。",-1)),t(a,{source:""})])}const g=r(d,[["render",o]]);export{I as __pageData,g as default};
